#include <chrono>
#include <mutex>
#include <semaphore>
#include <thread>
#include <vector>

int peakConcurrency(int workers, int permits)
{
    std::counting_semaphore<> gate{ permits };
    std::mutex countMutex{};
    int inside{ 0 };
    int peak{ 0 };
    {
        std::vector<std::jthread> threads{};
        for (int w{ 0 }; w < workers; ++w)
        {
            threads.emplace_back([&]
            {
                gate.acquire();
                {
                    std::scoped_lock lock{ countMutex };
                    ++inside;
                    if (inside > peak)
                    {
                        peak = inside;
                    }
                }
                std::this_thread::sleep_for(std::chrono::milliseconds{ 5 });
                {
                    std::scoped_lock lock{ countMutex };
                    --inside;
                }
                gate.release();
            });
        }
    }
    return peak;
}

unitTests:
TEST("never more than the permits allow") { const int p{ peakConcurrency(12, 3) }; CHECK(p >= 1); CHECK(p <= 3); }
TEST("one permit means one at a time") { CHECK_EQ(peakConcurrency(6, 1), 1); }
TEST("plenty of permits lets several in together") { CHECK(peakConcurrency(8, 8) >= 2); }
TEST("no workers") { CHECK_EQ(peakConcurrency(0, 2), 0); }

